// The autopilot's parsers (3.23-autopilot.md, "The loop (router `pa`)" and "Stops, holds and decisions"): the expert's,
// the closer's and the auditor's returns, and the POSIX-style splitter of Claude's `plan_edit` commands. Pure, no `$`.

/** An expert's (or the closer's) return; '' for a field it does not carry. `status` is lower-case. */
export type ExpertContract = {
  status: string
  log: string
  ctx: string
  commit: string
  milestone: string
  recommended: string
  question: string
  /** 3.23 T13: the plain-English summary of 2-4 sentences (optional; '' when absent). */
  summary: string
}

/** A coder's return, as far as its finish card reads it (3.23 T13). */
export type CoderReturn = { status: string; summary: string; commit: string }

/** The auditor's return (agents/auditor.md, "Return only"). */
export type AuditorReturn = {
  status: string
  verdicts: string
  fixed: string
  candidates: string
  file: string
  recommended: string
}

// As pa/hooks/user_prompt_submit.py:30-31: the first STATUS within the first 2000 chars.
const STATUS_RE = /STATUS\s*[:=]\s*([A-Za-z-]+)/i
const STATUS_WINDOW = 2000
const FENCE_RE = /^\s*(```|~~~)/
const FIELD_RE = /^\s*([A-Za-z_]+)\s*[:=]\s?(.*)$/

/**
 * The fields after the first STATUS (STATUS within the first 2000 chars), by `KEY: value` lines; a line that is no known
 * key continues the field before it (QUESTION and RECOMMENDED may wrap), a blank line or a fence ends it. Null without
 * STATUS.
 */
function fieldsAfterStatus(text: string, keys: readonly string[]): Record<string, string> | null {
  const m = STATUS_RE.exec(text.slice(0, STATUS_WINDOW))
  if (m === null) {
    return null
  }
  const out: Record<string, string> = { status: (m[1] ?? '').toLowerCase() }
  scanFields(text.slice(m.index).split(/\r?\n/).slice(1), keys, out)
  return out
}

/** The `KEY: value` lines of `lines` into `out` (fieldsAfterStatus's reading). */
function scanFields(lines: readonly string[], keys: readonly string[], out: Record<string, string>): void {
  let current = ''
  for (const line of lines) {
    if (FENCE_RE.test(line) || line.trim() === '') {
      current = ''
      continue
    }
    const f = FIELD_RE.exec(line)
    const key = f === null ? '' : (f[1] ?? '').toLowerCase()
    if (f !== null && keys.includes(key)) {
      if (out[key] === undefined) {
        out[key] = (f[2] ?? '').trim()
        current = key
      } else {
        current = '' // a second block's field: never overwrites the first
      }
    } else if (key === 'status') {
      break // the next block
    } else if (current !== '') {
      out[current] = `${out[current] ?? ''}\n${line.trim()}`
    }
  }
}

// 3.25 T3 (3.25-loose.md, decision 2): the plain hand-back. The first non-blank line's first word, markdown and trailing
// punctuation stripped, when it is one of these; everything after it is free text.
const PLAIN_WORDS: readonly string[] = ['done', 'question', 'blocked', 'block', 'review', 'handoff', 'partial']
const PLAIN_RE = /^[\s#>*_-]*([A-Za-z]+)[\s*_:.,—–-]*(.*)$/
// A commit hash in free text: a 7-40 hex token after the word "commit" on the same line.
const COMMIT_IN_TEXT_RE = /\bcommit\w*\b[^\n]*?(?<![0-9a-z])([0-9a-f]{7,40})(?![0-9a-z])/i

/**
 * The legacy STATUS block's fields, else a plain report's: `status` the first word, `text` the free text after it (the
 * rest of the first line and the lines after, trimmed), any legacy `KEY:` lines among those lines as fields. Null with
 * neither (`.`, a blank text and `WAITING:` stay null).
 */
function looseFields(text: string, keys: readonly string[]): Record<string, string> | null {
  const legacy = fieldsAfterStatus(text, keys)
  if (legacy !== null) {
    return legacy
  }
  const lines = text.split(/\r?\n/)
  const i = lines.findIndex(l => l.trim() !== '')
  const m = i < 0 ? null : PLAIN_RE.exec(lines[i] ?? '')
  const word = (m?.[1] ?? '').toLowerCase()
  if (m === null || !PLAIN_WORDS.includes(word)) {
    return null
  }
  const out: Record<string, string> = { status: word }
  scanFields(lines.slice(i + 1), keys, out)
  out['text'] = [m[2] ?? '', ...lines.slice(i + 1)].join('\n').trim()
  return out
}

/** The commit: the `commit` field's leading hash, else the field as written; without one, a hash after "commit" in the text. */
function commitOf(f: Record<string, string>, text: string): string {
  const field = f['commit'] ?? ''
  const hash = /^\s*([0-9a-f]{7,40})(?![0-9a-z])/i.exec(field)?.[1]
  return hash ?? (field !== '' ? field : (COMMIT_IN_TEXT_RE.exec(text)?.[1] ?? ''))
}

const EXPERT_KEYS = ['log', 'ctx', 'commit', 'milestone', 'recommended', 'question', 'summary'] as const

/** An expert's return: the legacy block (`STATUS · LOG · CTX · COMMIT · MILESTONE · RECOMMENDED · QUESTION`, optional
 * `SUMMARY`) or a plain report (3.25 T3: `summary` the free text, and for a question `question` too); null with neither.
 * 3.28.8: a plain report's free text wins over a `Summary: <path>` line inside it (TerrainDiffusion T12's card showed
 * only that pointer line). */
export function parseExpertContract(text: string): ExpertContract | null {
  const f = looseFields(text, EXPERT_KEYS)
  if (f === null) {
    return null
  }
  const g = (k: string): string => f[k] ?? ''
  const free = g('text')
  return {
    status: g('status'), log: g('log'), ctx: g('ctx'), commit: commitOf(f, text), milestone: g('milestone'),
    recommended: g('recommended'), question: g('question') || (g('status') === 'question' ? free : ''),
    summary: free || g('summary'),
  }
}

// Every coder key, so none continues the field before it.
const CODER_KEYS = ['changed', 'verified', 'log', 'ctx', 'commit', 'deviations', 'blocker', 'summary'] as const

/** A coder's return (`STATUS · CHANGED · VERIFIED · … · COMMIT · … · SUMMARY`, or a plain report, 3.25 T3): its status,
 * summary and commit; null with neither.
 * 3.24 T12c: `commit` is the field's leading hash when it has one (`75c1b8d (rename, on top of e45aa75)` → `75c1b8d`), so
 * a coder's note after the hash still gives the finish card its commit and files; otherwise the field as written; without
 * the field, a hash after "commit" in the text. */
export function parseCoderReturn(text: string): CoderReturn | null {
  const f = looseFields(text, CODER_KEYS)
  return f === null ? null : { status: f['status'] ?? '', summary: (f['text'] ?? '') || (f['summary'] ?? ''), commit: commitOf(f, text) }
}

const AUDITOR_KEYS = ['verdicts', 'fixed', 'candidates', 'file', 'recommended'] as const

/** The auditor's return (`STATUS · VERDICTS · FIXED · CANDIDATES · FILE · RECOMMENDED`); null without STATUS. */
export function parseAuditorReturn(text: string): AuditorReturn | null {
  const f = fieldsAfterStatus(text, AUDITOR_KEYS)
  if (f === null) {
    return null
  }
  const g = (k: string): string => f[k] ?? ''
  return { status: g('status'), verdicts: g('verdicts'), fixed: g('fixed'), candidates: g('candidates'), file: g('file'), recommended: g('recommended') }
}

/** The only scripts a `plan_edit` command may run, after `PY`. */
export const ALLOWED_SCRIPTS: readonly string[] = ['tools/plan_edit.py', 'tools/rules_add.py']
/** The phase close's `RUN:` lines (3.23 T6b): plan_edit.py gen-close and genend_index.py assemble. */
export const CHAIN_SCRIPTS: readonly string[] = [...ALLOWED_SCRIPTS, 'tools/genend_index.py']

export type Split = { argv: string[] } | { refused: string }

/**
 * Claude's `plan_edit` command as argv, never through a shell: split POSIX-style (single quotes literal; in double quotes
 * a backslash escapes `\ " $` and the backtick; outside quotes a backslash escapes any character). Refused where a shell
 * would substitute (`$(` or a backtick outside single quotes, unescaped) or chain or redirect (`;`, `&&`, `|`, `<`, `>`
 * outside quotes); an unterminated quote; any script but `tools/plan_edit.py` or `tools/rules_add.py`. The script may
 * follow `PY` or any interpreter-looking token, stand first, or be left out (bare args mean plan_edit.py; rules_add.py
 * only when named). The interpreter becomes `python`, one argv element. `allowed` widens the scripts (CHAIN_SCRIPTS).
 */
export function splitCommand(line: string, python: string, allowed: readonly string[] = ALLOWED_SCRIPTS): Split {
  const argv: string[] = []
  let word = ''
  let inWord = false
  let quote: '' | "'" | '"' = ''
  for (let i = 0; i < line.length; i += 1) {
    const c = line[i] ?? ''
    const next = line[i + 1] ?? ''
    if (quote === "'") {
      if (c === "'") {
        quote = ''
      } else {
        word += c
      }
      continue
    }
    if (c === '\\') {
      if (quote === '"') {
        if (next === '\\' || next === '"' || next === '$' || next === '`') {
          word += next
          i += 1
        } else if (next === '\n') {
          i += 1
        } else {
          word += c
        }
      } else if (next === '\n') {
        i += 1
      } else if (next !== '') {
        word += next
        inWord = true
        i += 1
      } else {
        word += c
        inWord = true
      }
      continue
    }
    if (c === '`') {
      return { refused: 'a backtick outside single quotes' }
    }
    if (c === '$' && next === '(') {
      return { refused: '$( command substitution' }
    }
    if (quote === '"') {
      if (c === '"') {
        quote = ''
      } else {
        word += c
      }
      continue
    }
    if (c === ';' || c === '|' || c === '<' || c === '>') {
      return { refused: `${c} outside quotes` }
    }
    if (c === '&' && next === '&') {
      return { refused: '&& outside quotes' }
    }
    if (c === "'" || c === '"') {
      quote = c
      inWord = true
      continue
    }
    if (c === ' ' || c === '\t' || c === '\n' || c === '\r') {
      if (inWord) {
        argv.push(word)
        word = ''
        inWord = false
      }
      continue
    }
    word += c
    inWord = true
  }
  if (quote !== '') {
    return { refused: 'an unterminated quote' }
  }
  if (inWord) {
    argv.push(word)
  }
  if (argv.length === 0) {
    return { refused: 'an empty command' }
  }
  // The forms Claude writes: `PY <script> …`, `<interpreter> <script> …`, `<script> …`, or bare plan_edit.py args.
  const rest = isInterpreter(argv[0] ?? '') ? argv.slice(1) : argv
  const first = rest[0] ?? ''
  const script = scriptOf(first, allowed)
  let args: string[]
  if (script !== null) {
    args = [script, ...rest.slice(1)]
  } else if (rest !== argv || !/^[a-z][a-z-]*$/.test(first)) {
    return { refused: `not an allowed script: ${first === '' ? '(none)' : first}` }
  } else if (SHELLS.includes(first)) {
    return { refused: `${first} runs nothing here: only tools/plan_edit.py or tools/rules_add.py` }
  } else {
    args = ['tools/plan_edit.py', ...rest] // bare args mean plan_edit.py
  }
  if (python === '') {
    return { refused: 'no python in pa.json' }
  }
  return { argv: [python, ...args] }
}

// Bare args go to plan_edit.py, whose argparse refuses an unknown subcommand; a shell's name gets a plain refusal instead.
const SHELLS = ['bash', 'sh', 'zsh', 'cmd', 'powershell', 'pwsh', 'env', 'exec']

/** `PY`, or a token naming a Python interpreter (`python`, `python3.14`, `py`, `…/python.exe`). */
function isInterpreter(tok: string): boolean {
  const base = tok.split(/[\\/]/).pop() ?? ''
  return tok === 'PY' || /^(python[\d.]*|py)(\.exe)?$/i.test(base)
}

/** The allowed script a token names (`tools/plan_edit.py`, `./tools/plan_edit.py`, `plan_edit.py`, backslashes), else null. */
function scriptOf(tok: string, allowed: readonly string[]): string | null {
  const t = tok.replace(/\\/g, '/').replace(/^\.\//, '')
  return allowed.find(s => t === s || t === s.slice('tools/'.length)) ?? null
}

files.hooks/debug.ts:
// Pure helpers of the router's wiring: debug event files (one JSON file per event under PA_MOD_DEBUG=1, since `$.fs`
// has no append), the generation token, and the argv of the prune of old `.run/mod/<sid>` folders.

/** One file per event, sortable by time then by a per-load counter. */
export function eventFile(dir: string, ms: number, n: number, kind: string): string {
  const safe = kind.replace(/[^a-z0-9.]+/gi, '_')
  return `${dir}/${String(ms)}-${String(n).padStart(5, '0')}-${safe}.json`
}

/** A value as text, cut to `n` characters, so event files stay small. */
export function clip(value: unknown, n: number): string {
  let text: string
  if (typeof value === 'string') {
    text = value
  } else {
    try {
      text = JSON.stringify(value) ?? String(value)
    } catch {
      text = String(value)
    }
  }
  return text.length > n ? `${text.slice(0, n)}…` : text
}

/**
 * A tick holds the generation it was armed under; `/clear` resets `$.state` (the current generation reads 0) and
 * re-arming bumps it, so a tick whose token differs from the current one is stale and stops.
 */
export function isStale(tickGen: number, currentGen: number): boolean {
  return tickGen !== currentGen
}

/** `.run/mod/<sid>` folders untouched this many days are pruned at session start. */
export const PRUNE_DAYS = 14

// argv: base, days, then the folder names to keep. A folder's age is the newer of its own and its state.json mtime;
// only 36-character names (session ids) are candidates. Prints how many it removed.
const PRUNE_SCRIPT =
  'import os,sys,time,shutil;b=sys.argv[1];c=time.time()-float(sys.argv[2])*86400;k=set(sys.argv[3:]);' +
  "s=lambda p:max(os.path.getmtime(p),os.path.getmtime(os.path.join(p,'state.json')) if os.path.exists(os.path.join(p,'state.json')) else 0);" +
  'o=[os.path.join(b,x) for x in (os.listdir(b) if os.path.isdir(b) else []) if len(x)==36 and x not in k and os.path.isdir(os.path.join(b,x))];' +
  'o=[p for p in o if s(p)<c];[shutil.rmtree(p,ignore_errors=True) for p in o];print(len(o))'

/** The `$.process.run` argv of the prune, or null when pa.json names no interpreter. */
export function pruneArgv(python: string, base: string, keep: readonly string[], days: number): string[] | null {
  if (python === '') {
    return null
  }
  return [python, '-c', PRUNE_SCRIPT, base, String(days), ...keep.filter(k => k !== '')]
}

files.hooks/inbox.ts:
// The router's inbox `.run/mod/<sid>/inbox/` (design.md, "The plugins talk through files"): the watcher writes one file
// per tool request, `<ms>-<seq>-<kind>.json` holding `{id, kind, caller, input, at}`; the router's one-second tick
// drains it. Pure: naming, parsing, which files are owed, and the handler table. A handler returns effects (data) that
// the drain performs inline, since `$` cannot be passed to a helper.

import type { ToastOut } from '../types'

import { presentOf } from './planview'
import { DONE_TTL_MS, type Present } from './state'

export type Request = { id: string; kind: string; caller: string; input: unknown; at: number }

export type RequestName = { id: string; ms: number; seq: number; kind: string }

/** What a handler asks the drain to do: the debug log; T8a: the topic flag on the calling partner, a waiting toast;
 * T8c: a dialog queued for the presentation tick (planview.ts); 3.23 T5b: a loop notice queued as a framed `other`
 * message for `to` (a request's caller), else the partner; T13b: a loop stop's toast cause owed to Claude's next reply
 * (`stop`; null clears it); 3.24 T13E: a card the loop drew (`card`: registered, journaled, drawn at zero tokens). */
export type Effect =
  | { do: 'log'; kind: string; data: Record<string, unknown> }
  | { do: 'topic'; agentId: string }
  | { do: 'toast'; cause: ToastOut['cause']; body: string }
  | { do: 'present'; item: Present }
  | { do: 'notice'; text: string; to: string }
  | { do: 'stop'; cause: ToastOut['cause'] | null }
  | { do: 'card'; text: string }

/**
 * Kinds the loop's tick drains itself (autopilot.tsx, marked done in loop.json); the router's drain skips them. T5d2a:
 * `forward`, written by the router when it queues a forward of a child's hand-back to the loop's expert. T6a1: the
 * router's `install` (an approved generation or phase plan) and `answer` (the answer to the loop's own `ask`).
 */
export const LOOP_KINDS: ReadonlySet<string> = new Set(['release', 'plan_edit', 'steer', 'forward', 'install', 'answer', 'cleanup'])

/** A file name's kind is one the loop drains. */
export const isLoopKind = (name: string): boolean => LOOP_KINDS.has(parseRequestName(name)?.kind ?? '')

export type Handler = (req: Request) => Effect[]

const KIND = /^[a-z][a-z0-9_]*$/

/** The file name of a request; its id is the name without `.json`. */
export function requestName(ms: number, seq: number, kind: string): string {
  if (!KIND.test(kind)) {
    throw new Error(`bad request kind: ${kind}`)
  }
  return `${String(ms)}-${String(seq)}-${kind}.json`
}

export function parseRequestName(name: string): RequestName | null {
  const m = /^(\d+)-(\d+)-([a-z][a-z0-9_]*)\.json$/.exec(name)
  if (m === null) {
    return null
  }
  return { id: name.slice(0, -'.json'.length), ms: Number(m[1]), seq: Number(m[2]), kind: m[3] ?? '' }
}

/** The request a file holds, or null when it does not parse or its id or kind disagrees with its name. */
export function parseRequest(text: string, name: string): Request | null {
  const n = parseRequestName(name)
  if (n === null) {
    return null
  }
  let doc: unknown
  try {
    doc = JSON.parse(text)
  } catch {
    return null
  }
  if (typeof doc !== 'object' || doc === null || Array.isArray(doc)) {
    return null
  }
  const o = doc as Record<string, unknown>
  if (o['id'] !== n.id || o['kind'] !== n.kind) {
    return null
  }
  return {
    id: n.id,
    kind: n.kind,
    caller: typeof o['caller'] === 'string' ? o['caller'] : '',
    input: o['input'] ?? null,
    at: typeof o['at'] === 'number' ? o['at'] : n.ms,
  }
}

/** The request files owed: well named, not done, inside the horizon; oldest first (ms, then seq). */
export function pendingRequests(names: readonly string[], done: Readonly<Record<string, number>>, now: number,
  ttl: number = DONE_TTL_MS): string[] {
  const owed: RequestName[] = []
  for (const name of names) {
    const n = parseRequestName(name)
    if (n !== null && done[n.id] === undefined && now - n.ms <= ttl) {
      owed.push(n)
    }
  }
  owed.sort((a, b) => a.ms - b.ms || a.seq - b.seq || (a.kind < b.kind ? -1 : a.kind > b.kind ? 1 : 0))
  return owed.map(n => `${n.id}.json`)
}

const noop: Handler = req => [{ do: 'log', kind: 'inbox.drain', data: { id: req.id, kind: req.kind } }]

const inputText = (input: unknown, key: string): string => {
  const v = typeof input === 'object' && input !== null ? (input as Record<string, unknown>)[key] : undefined
  return typeof v === 'string' ? v : ''
}

/** A `plan` or `ask` queued for the presentation tick; an input it cannot read is logged and dropped. */
const presentFx = (req: Request): Effect[] => {
  const item = presentOf(req)
  return item === null
    ? [{ do: 'log', kind: 'present.bad', data: { id: req.id, kind: req.kind } }]
    : [{ do: 'present', item }]
}

const CAUSES: readonly ToastOut['cause'][] = ['review', 'question', 'input']

/** A loop notice (`caller: "loop"`, input `{text, toast?, to?}`): the text to `to` or the partner; a named toast is a
 * stop's, owed to Claude's next reply (T13b: one toast per stop, none at the notice). */
const noticeFx = (req: Request): Effect[] => {
  const text = inputText(req.input, 'text')
  if (text.trim() === '') {
    return [{ do: 'log', kind: 'notice.bad', data: { id: req.id } }]
  }
  const cause = CAUSES.find(c => c === inputText(req.input, 'toast'))
  const fx: Effect[] = [{ do: 'notice', text, to: inputText(req.input, 'to') }]
  return cause === undefined ? fx : [...fx, { do: 'stop', cause }]
}

/** kind -> handler; any other kind goes to `noop`. `ask` raises the toast and queues the picker (Claude's ask takes a
 * pending stop's place, T13b); `plan` queues path 0. */
export const HANDLERS: Readonly<Record<string, Handler>> = {
  topic: req => [...noop(req), { do: 'topic', agentId: req.caller }],
  ask: req => [...noop(req), { do: 'toast', cause: 'input', body: inputText(req.input, 'question') },
    ...(req.caller === 'loop' ? [] : [{ do: 'stop', cause: null } as const]), ...presentFx(req)],
  plan: req => [...noop(req), ...presentFx(req)],
  notice: req => [...noop(req), ...noticeFx(req)],
  // 3.23 T13d.c4: a toast raised at once, no Claude turn (the generation end's closed line; input `{cause, body}`).
  toast: req => [...noop(req), { do: 'toast', cause: CAUSES.find(c => c === inputText(req.input, 'cause')) ?? 'input', body: inputText(req.input, 'body') }],
  // 3.24 T13E: a card of the loop's (input `{text}`, a cardText; the review release's "✓ Expert · T<n> · accepted").
  card: req => [...noop(req), ...(inputText(req.input, 'text').trim() === ''
    ? [{ do: 'log', kind: 'card.bad', data: { id: req.id } } as const]
    : [{ do: 'card', text: inputText(req.input, 'text') } as const])],
}

/** A loop notice request: its file name and body, in the format `parseRequest` reads. */
export function noticeRequest(ms: number, seq: number, text: string, toast: ToastOut['cause'] | '' = '', to = ''):
  { name: string; body: string } {
  const name = requestName(ms, seq, 'notice')
  const input: Record<string, string> = { text }
  if (toast !== '') {
    input['toast'] = toast
  }
  if (to !== '') {
    input['to'] = to
  }
  return { name, body: JSON.stringify({ id: name.slice(0, -'.json'.length), kind: 'notice', caller: 'loop', input, at: ms }, null, 1) }
}

/** The router's `forward` request (3.23 T5d2a): a forward of `child`'s hand-back to the loop expert `agentId` is queued. */
export function forwardRequest(ms: number, seq: number, agentId: string, child: string): { name: string; body: string } {
  const name = requestName(ms, seq, 'forward')
  return { name, body: JSON.stringify({ id: name.slice(0, -'.json'.length), kind: 'forward', caller: 'router', input: { agentId, child }, at: ms }, null, 1) }
}

/** Any request file (3.23 T6a1: the router's `install` and `answer`, the loop's `ask` with caller `loop`). */
export function requestFile(ms: number, seq: number, kind: string, caller: string, input: unknown): { name: string; body: string } {
  const name = requestName(ms, seq, kind)
  return { name, body: JSON.stringify({ id: name.slice(0, -'.json'.length), kind, caller, input, at: ms }, null, 1) }
}

export function handle(req: Request): Effect[] {
  return (HANDLERS[req.kind] ?? noop)(req)
}

